<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { useCartStore } from '../stores/cart'
import { currency } from '../services/api'
import LoadingState from '../components/LoadingState.vue'
const cart=useCartStore();const loading=ref(true);const error=ref('');const mutating=ref<string|null>(null)
onMounted(async()=>{try{await cart.fetch()}catch(e){error.value=e instanceof Error?e.message:'Gagal memuat keranjang'}finally{loading.value=false}})
async function update(id:string,q:number){mutating.value=id;error.value='';try{await cart.update(id,q)}catch(e){error.value=e instanceof Error?e.message:'Gagal memperbarui keranjang'}finally{mutating.value=null}}
async function remove(id:string){mutating.value=id;error.value='';try{await cart.remove(id)}catch(e){error.value=e instanceof Error?e.message:'Gagal menghapus item'}finally{mutating.value=null}}
</script>
<template><section class="page-intro"><p class="eyebrow">RINGKASAN PILIHAN</p><h1>Keranjang belanja</h1><p>Periksa barang pilihanmu sebelum melanjutkan ke checkout.</p></section><LoadingState v-if="loading"/><p v-if="error" class="error-banner">{{ error }}</p><div v-if="!loading&&cart.cart?.items.length" class="cart-layout"><div class="cart-items"> <article v-for="item in cart.cart.items" :key="item.id" class="cart-item"><RouterLink :to="{name:'product-detail',params:{slug:item.product.slug}}"><img :src="item.product.image_url" :alt="item.product.name"/></RouterLink><div class="cart-item-main"><RouterLink :to="{name:'product-detail',params:{slug:item.product.slug}}" class="product-name">{{ item.product.name }}</RouterLink><small class="muted">SKU: {{ item.sku }} · {{ Object.values(item.attributes).join(' / ') }}</small><span class="cart-unit-price">{{ currency(item.price) }}</span><button class="link-button danger-text" @click="remove(item.id)" :disabled="mutating===item.id">Hapus</button></div><div class="cart-item-end"><strong>{{ currency(item.line_total) }}</strong><div class="quantity-control"><button :disabled="item.quantity<=1||mutating===item.id" @click="update(item.id,item.quantity-1)">−</button><span>{{ item.quantity }}</span><button :disabled="item.quantity>=Math.min(99,item.stock_available)||mutating===item.id" @click="update(item.id,item.quantity+1)">+</button></div><small class="muted">Stok {{ item.stock_available }}</small></div></article></div><aside class="summary-card"><h2>Ringkasan belanja</h2><div class="summary-line"><span>Jumlah item</span><strong>{{ cart.count }}</strong></div><div class="summary-line"><span>Subtotal</span><strong>{{ currency(cart.subtotal) }}</strong></div><div class="summary-line muted"><span>Ongkir</span><span>Dihitung saat checkout</span></div><div class="summary-total"><span>Subtotal</span><strong>{{ currency(cart.subtotal) }}</strong></div><p class="muted small">Ongkir gratis untuk subtotal minimal Rp200.000 pada layanan reguler.</p><RouterLink to="/checkout" class="button-primary full-button">Lanjut ke checkout →</RouterLink><RouterLink to="/products" class="button-secondary full-button">Lanjut belanja</RouterLink></aside></div><div v-else-if="!loading" class="empty-state large-empty"><div class="empty-symbol">♧</div><h3>Keranjangmu masih kosong</h3><p>Temukan produk yang kamu suka lalu tambahkan ke keranjang.</p><RouterLink to="/products" class="button-primary">Mulai belanja</RouterLink></div></template>
